  "privacyUi.helpShapeStykanimate": "Hjelp til med å forme StykAnimate",
  "privacyUi.closePrivacySettings": "Lukk personverninnstillinger",
  "privacyUi.yourAnimationsFilenamesAndTextStayOutOf": "Animasjoner, filnavn og tekst tas ikke med i rapporter.",
  "privacyUi.accept": "Godta",
  "privacyUi.reject": "Avslå",
  "privacyUi.acceptSharesBothRejectKeepsBothOff": "Med «Godta» deles begge datatypene. Med «Avslå» forblir begge valgene deaktivert.",
  "privacyUi.youCanChangeYourChoicesAnyTimeIn": "Du kan endre valgene når som helst i Innstillinger.",
  "privacyUi.chooseSeparatelySeeDetails": "Velg hver for seg og se detaljer",
  "privacyUi.shareOnlyWhatYouReComfortableWith": "Del bare det du er komfortabel med.",
  "privacyUi.bothOptionsAreOptionalTheEditorWorksWith": "Begge valgene er frivillige. Programmet fungerer selv om ett eller begge valgene er slått av.",
  "privacyUi.productAnalytics": "Produktanalyse",
  "privacyUi.featureCountsActiveAndIdleTimeTimelineMode": "Antall ganger funksjoner brukes, aktiv tid og inaktiv tid, tidslinjemodus, datoer for første redigering/lagring/eksport og grove tidsintervaller frem til første lagring/eksport. Inkluderer appversjon/utgave, testutgavestatus, overordnede kategorier for operativsystem/maskinvare og språk.",
  "privacyUi.performanceErrorDiagnostics": "Ytelses- og feildiagnostikk",
  "privacyUi.sampledEditingAndRenderingTimingsPlaybackMemoryUse": "Utvalg av redigerings- og gjengivelsestider, avspilling, minnebruk før og etter operasjoner, hurtigbuffer- og gjenopprettingsresultater og overordnede maskinvarekategorier. Små sammendrag ved alvorlige pauser inneholder tider og grove arbeidslastinnstillinger. Operasjonstider inkluderer format og intervaller for filstørrelse, kompleksitet og mål-FPS. Sladdede feilmeldinger inkluderer trygge koder, operasjonsfaser og kildesteder i StykAnimate. Inkluderer også appversjon/utgave og testutgavestatus.",
  "privacyUi.saveCustomChoices": "Lagre egne valg",
  "privacyUi.whatHappensToMyData": "Hva skjer med dataene mine?",
  "privacyUi.stykanimateIsTheControllerContact": "StykAnimate er behandlingsansvarlig. Kontakt",
  "privacyUi.aleRipresoGmailCom": "ale.ripreso@gmail.com",
  "privacyUi.aboutAccessCorrectionDeletionOrOtherPrivacyRights": "om innsyn, retting, sletting eller andre personvernrettigheter. Frivillig rapportering bygger på samtykket ditt; å trekke det tilbake endrer ikke lovligheten av tidligere behandling. Du kan klage til din lokale personvernmyndighet.",
  "privacyUi.aRandomInstallationIdLinksYourReportsIt": "En tilfeldig installasjons-ID knytter rapportene sammen. Den er ikke navnet eller kontoen din, men tilknyttede data er pseudonyme, ikke anonyme. Rutinerapporter utelater prosjektinnhold, navn, filstier, tekst, tastetrykk, skjermbilder, opptak og rå feilmeldinger. Det finnes ingen øktopptak eller reklamesporing.",
  "privacyUi.reportsAreEncryptedInTransitToOurCustom": "Rapporter krypteres under overføring til vår egen Cloudflare-tjeneste. Tilknyttede sammendrag og diagnostikk beholdes i 30 dager; innsendt tilbakemelding i 90 dager. Daglig statistikk fra minst fem installasjoner kan beholdes i 365 dager etter at identifikatorer er fjernet. Så lenge tilknyttede kildedata finnes, fjerner eller gjenoppbygger sletting også berørte daglige summer. Historiske anonyme summer kan ikke spores tilbake når tilknyttede kilder er utløpt. Lokale usendte sammendrag utløper etter sju dager.",
  "privacyUi.cloudflareProcessesNetworkRequestsAsOurHostingProvider": "Cloudflare behandler nettverksforespørsler som vår vertstjeneste og kan håndtere IP-adresser i infrastrukturen sin. StykAnimate legger ikke IP-adresser i analysedatabasen. Vertstjenester kan behandle data internasjonalt under sine gjeldende overføringsgarantier. Ingen valgfrie data sendes før du har valgt. Denne informasjonen har versjon 2026-09-10.",
  "privacyUi.inspectExportOrDeleteReports": "Se, eksporter eller slett rapporter",
  "privacyUi.previewShowsExactlyTheLocallyQueuedReportFields": "Forhåndsvisningen viser nøyaktig feltene i rapporter som står i lokal kø. Ditt private token autentiserer forespørsler til tjenesten og utelates fra forhåndsvisninger og eksporter.",
  "privacyUi.previewQueuedData": "Forhåndsvis data i kø",
  "privacyUi.saveReportJson": "Lagre rapport som JSON",
  "privacyUi.deleteMyDataTurnOff": "Slett dataene mine og slå av",
  "privacyUi.aHashOnlyDeletionMarkerIsKeptFor": "En slettemarkør som bare inneholder en hash, beholdes i 30 dager for å hindre at forsinkede opplastinger gjenskaper slettede rapporter. Hvis du er frakoblet, prøves slettingen på nytt senere. Behold denne appprofilen til du får bekreftelse. Sletting av tilknyttede rapporter kan ikke fjerne historiske summer som ikke lenger kan knyttes til denne installasjonen.",
  "privacyUi.reportAProblemOrShareAnIdea": "Rapporter et problem eller del en idé",
  "privacyUi.privateSupportConversationsAreSeparateFromOptionalProfiling": "Private støttesamtaler er atskilt fra frivillig profilering. Du kan legge ved utvalgte bilder eller .styk-filer og følge svar her. Samtaler utløper etter 90 dager og vedlegg etter 30 dager. Lagre den private tilgangslenken for å komme tilbake på en annen enhet. Slett en støtterapport inne i samtalen; sletting av valgfri diagnostikk sletter ikke den separate støtteinnboksen. Åpne den fra Hjelp eller Innstillinger → Tilbakemelding.",
  "privacyUi.sendFeedbackOrReportABug": "Send tilbakemelding eller rapporter en feil",
  "privacyUi.recordAPerformanceTraceLocally": "Ta opp ytelsessporing lokalt",
  "privacyUi.startA30SecondTraceThenReproduceA": "Start en sporing på 30 sekunder og gjenskap deretter en treg handling i programmet. Opptaket gir midlertidig ekstra belastning. Spor kan inneholde funksjonsnavn, URL-er og lokale stier: se gjennom filen før deling. Den lastes aldri opp automatisk.",
  "privacyUi.record30SecondTrace": "Ta opp sporing i 30 sekunder",
  "privacyUi.forManualAnalysisInChromeTracingOrPerfetto": "For manuell analyse i Chrome tracing eller Perfetto. Vanlig rapportering bruker små statistiske sammendrag.",
